enum Status{
    Ok = 200,
    Error = 404,
    Pending = 202
}

fn handleStatus(status: Status) {
    when (status){
        (Status.Ok)  println("Success: {status}"),
        (Status.Error)  println("Error: {status}"),
        (Status.Pending)  println("Processing...")   
    }
}
